3. Создайте новый файл `Dockerfile` в корневой папке вашего проекта. В этом файле, напишите следующий код:

```
FROM cypress/base:14.17.0

# Install Cypress CLI and plugins
RUN npm install cypress --save-dev && \
    npm install cypress-multi-reporters --save-dev && \
    npm install cypress-esbuild-preprocess --save-dev && \
    npm install cypress-puppeteer --save-dev

# Add plugins for screenshots and videos
RUN mkdir -p cypress/plugins && \
    cat > cypress/plugins/index.js << EOF
    module.exports = (on, config) => {
      on('before:browser:launch', (browser, launchOptions) => {
        if (browser.name === 'chrome' || browser.name === 'chrome:canary') {
          launchOptions.args.push('--headless');
          launchOptions.args.push('--disable-infobars');
          launchOptions.args.push('--window-size=1280,720');
          launchOptions.args.push('--no-sandbox');
          launchOptions.args.push('--disable-setuid-sandbox');
        }
        return launchOptions;
      });

      on('task', { name: 'screenshot', options: { path: null } }, async (task, options) => {
        const { page } = Cypress.browser;
        const { $, click } = Cypress;
        await page.goto(config.baseUrl, { waitUntil: 'networkidle0' });
        await $.customWait(500);
        await click('[data-cy="take-screenshot"]');
        const { body } = await page.$('body');
        const base64 = await body?.screenshot();
        if (options.path) {
          await Cypress.fs.writeFile(options.path, Buffer.from(base64, 'base64'));
        }
        return base64;
      });

      on('task', { name: 'video', options: { path: null } }, async (task, options) => {
        const { page } = Cypress.browser;
        const { $, click } = Cypress;
        await page.goto(config.baseUrl, { waitUntil: 'networkidle0' });
        await $.customWait(500);
        await click('[data-cy="start-recording"]');
        const { body } = await page.$('body');
        const video = await body?.$eval('video', el => el.captureStream().getTracks()[0]);
        if (options.path) {
          const stream = await video?.getTracks()[0].clone();
          const recorder = new MediaRecorder(stream, { mimeType: 'video/webm; codecs=vp9,opus' });
          const chunks = [];
          recorder.ondataavailable = event => chunks.push(event.data);
          await new Promise(resolve => recorder.start(10).then(() => setTimeout(resolve, 300000)));
          recorder.stop();
          const blob = new Blob(chunks, { type: recorder.mimeType });
          await Cypress.fs.writeFile(options.path, blob);
        }
        return true;
      });
    };
    EOF

# Add Cypress configuration file
COPY cypress/cypress.json ./

# Add test files
COPY cypress/**/*.spec.js cypress/

# Add screenshots and videos folder
RUN mkdir -p cypress/screenshots && \
    mkdir -p cypress/videos

# Expose Cypress test runner port
EXPOSE 4444

# Set working directory
WORKDIR /cypress
```

